    46  static void view_sam(const uint8_t *data, size_t size, char *mode,
    47                       int close_abort) {
    48      uint8_t *copy = malloc(size);
    49      if (copy == NULL) {
    50          abort();
    51      }
    52      memcpy(copy, data, size);
    53
    54      hFILE *memfile = hopen("mem:", "rb:", copy, size);
    55      if (memfile == NULL) {
    56          free(copy);
    57          return;
    58      }
    59
    60      htsFile *in = hts_hopen(memfile, "data", "rb");
    61      if (in == NULL) {
    62          if (hclose(memfile) != 0)
    63              abort();
    64          return;
    65      }
    66
    67      samFile *out = sam_open("/dev/null", mode);
    68      if (!out)
    69          abort();
    70
    71  #ifdef FUZZ_FAI
    72      // Not critical if this doesn't work, but can test more if
    73      // we're in the right location.
    74      //
    75      // We can't rely on what the pwd is for the OSS-fuzz so we don't enable
    76      // this by default.
    77      if (hts_set_fai_filename(out, "../c2.fa") < 0) {
    78          static int warned = 0;
    79          if (!warned) {
    80              warned = 1;
    81              fprintf(stderr, "Warning couldn't find the c2.fa file\n");
    82          }
    83      }
    84  #endif
    85
    86      sam_hdr_t *hdr = sam_hdr_read(in);
    87      if (hdr == NULL) {
    88          if (close_abort)
    89              hts_close_or_abort(out);
    90          else
    91              hts_close(out);
    92          hts_close(in);
    93          return;
    94      }
    95
    96      // This will force the header to be parsed.
    97      (void) sam_hdr_count_lines(hdr, "SQ");
    98
    99      if (sam_hdr_write(out, hdr) != 0)
   100          goto err;
   101
   102      bam1_t *b = bam_init1();
   103      if (b == NULL)
   104          goto err;
   105
   106      while (sam_read1(in, hdr, b) >= 0) {
   107          if (sam_write1(out, hdr, b) < 0)
   108              break;
   109      }
   110      bam_destroy1(b);
   111
   112   err:
   113      sam_hdr_destroy(hdr);
   114      if (close_abort)
   115          hts_close_or_abort(out);
   116      else
   117          hts_close(out);
   118      hts_close(in);
   119  }
